"""Brute-force / exact solvers for ThreeSat and VertexCover (testing only)."""

from __future__ import annotations

from functools import lru_cache
from itertools import product


def solve_three_sat(instance: dict) -> bool:
    """True iff some assignment satisfies every clause."""
    num_vars = instance["num_vars"]
    clauses = instance["clauses"]
    for assignment in product([False, True], repeat=num_vars):
        ok = True
        for clause in clauses:
            if not any(
                (lit > 0 and assignment[abs(lit) - 1])
                or (lit < 0 and not assignment[abs(lit) - 1])
                for lit in clause
            ):
                ok = False
                break
        if ok:
            return True
    return False


def solve_vertex_cover(instance: dict) -> bool:
    """Exact: True iff there is a vertex cover of size at most k."""
    n = instance["n"]
    edges = [tuple(e) for e in instance["edges"]]
    k = instance["k"]
    if k < 0:
        return False
    if not edges:
        return True
    if k >= n:
        return True

    def rec(remaining, budget):
        if not remaining:
            return True
        if budget <= 0:
            return False
        # Branch on an edge: cover it by either endpoint.
        u, v = remaining[0]
        without_u = [e for e in remaining if u not in e]
        if rec(without_u, budget - 1):
            return True
        without_v = [e for e in remaining if v not in e]
        return rec(without_v, budget - 1)

    return rec(edges, k)
